insert into public.events (id,slug,title_ja,title_zh,category,summary,fees,conditions,status,verified_at,updated_at,image,gallery,translated_rules,benefits) values ('ournotes-sweets-2026','ournotes-sweets-paradise-2026','BanG Dream! Our Notes × SWEETS PARADISE','Our Notes × SWEETS PARADISE 联动咖啡厅','联动咖啡厅','五支乐队的联动咖啡厅，九地门店统一收录。包含官方菜单、周边和特典图片，以及入店、点单、限购与预约规则的中文说明；各门店日期和余量请分别确认。','自助餐：成人平日 ¥1,790 / 周末及节假日 ¥1,990，儿童 ¥1,040；联动餐食、甜点每份 ¥990，饮品每杯 ¥770，均另付费且含税。','["须购买自助餐及联动菜单；只有实际使用联动菜单的顾客能购买周边。","餐食和甜点只能首次点单；每人合计最多 5 份。首次饮品最多 10 杯。","周边每人每次入店仅 1 次结账，具体限购见中文规则及官方图片。","各店活动日期不同；商品和赠品余量未知，出发前查看官方公告并向门店确认。"]','published','2026-10-27T19:37:07.376Z','2026-10-27T19:37:07.376Z','{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/09/2608_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%82%A2%E3%82%A4%E3%82%AD%E3%83%A3%E3%83%83%E3%83%81%E7%94%BB%E5%83%8F_w750%C3%97h511.jpg","alt":"BanG Dream! Our Notes × SWEETS PARADISE 联动咖啡厅官方主视觉","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"}','[{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/09/2608_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_KV_0902FIX_%E7%AD%89%E8%BA%AB.jpg","alt":"五支乐队等身主视觉","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/09/2608_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_KV_0902FIX_%E3%83%9F%E3%83%8B%E3%82%AD%E3%83%A3%E3%83%A9.jpg","alt":"五支乐队迷你角色主视觉","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_01.jpg","alt":"餐食、甜点与自助餐费用","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_02.jpg","alt":"饮品、吸管卡与热饮图案分组","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_03.jpg","alt":"纸餐垫与杯垫领取规则","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2610_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E6%B3%A8%E6%96%87%E5%88%B6%E9%99%90POP.jpg","alt":"餐食及饮品点单限制","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2610_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E8%B3%BC%E5%85%A5%E5%88%B6%E9%99%90POP.jpg","alt":"周边购买次数与数量限制","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2610_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%82%B0%E3%83%83%E3%82%BAPOP_1009.jpg","alt":"周边售价与意面零食内封贴纸","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"}]','[{"id":"sweets-entry","kind":"参加","title":"先吃联动餐饮，再买周边","text_zh":"入店需要购买自助餐套餐，联动餐食、甜点或饮品另付费。同组顾客需要购买相同套餐，即使其中有人不点联动菜单。只有实际使用联动菜单的顾客可以购买周边；不能只进店买周边。周边须在用餐时间内购买，不接受预订或留货。","evidence_ja":"コラボメニューをご飲食いただいたお客様のみ","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":null,"image_sha256":null,"checked_on":"2026-10-28"},{"id":"sweets-prices","kind":"参加","title":"自助餐与联动菜单分开收费","text_zh":"以下均为含税日元：成人自助餐平日 ¥1,790，周末及节假日 ¥1,990；儿童 ¥1,040（周末及节假日不变）。图片中的联动餐食、甜点每份 ¥990；联动饮品费用另见饮品菜单。因过敏等原因，不提供去除食材、替换食材或单独盛放服务。","evidence_ja":"大人（平日）1,790円","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_01.jpg","image_sha256":"e8fea6f40bbb844df621bf944e3b69a4f59920ef0a57eeaebe28bf0a7d55ab81","checked_on":"2026-10-28"},{"id":"sweets-ordering","kind":"点单","title":"首次餐食甜点合计 5 份，饮品 10 杯","text_zh":"每人首次点单：餐食与甜点合计最多 5 份，饮品最多 10 杯。已经送到的饮品全部喝完后，才能加点；每轮加点每人最多 5 杯，喝完后可再次追加。加点最晚到用餐结束前 30 分钟。杯垫随联动菜单提供，不能单买。","evidence_ja":"フード・デザート：合計5品まで","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2610_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E6%B3%A8%E6%96%87%E5%88%B6%E9%99%90POP.jpg","image_sha256":"fef1f6729a2316da84e5ca6fd621a30d6ec0892a36adb450bdc33adbba0c128f","checked_on":"2026-10-28"},{"id":"sweets-food-first","kind":"点单","title":"餐食、甜点只在入店时点单","text_zh":"餐食和甜点只能在入店的首次点单时购买，不能像饮品一样中途追加。先确认想要的菜单及数量，再提交首次点单。店内拥挤时，饮品追加可能受限制。","evidence_ja":"フード・デザートのご注文は入店時のみ","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":null,"image_sha256":null,"checked_on":"2026-10-28"},{"id":"sweets-drink","kind":"特典","title":"饮品 ¥770；吸管卡和热饮图案另有分组","text_zh":"联动饮品每杯 ¥770（含税）。各乐队冷饮附本乐队 5 款中随机 1 款吸管卡，不能指定成员。热饮可选咖啡欧蕾或牛奶可可，并选择 A / B 组图案：A 组 10 款（MyGO!!!!!、millsage），B 组 15 款（Ave Mujica、梦限大MewType、一家Dumb Rock!），组内随机。热饮上的可食用图案不是杯垫，数量也与杯垫不同。","evidence_ja":"ホットドリンクA（全10種）","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_02.jpg","image_sha256":"e0c9f97891882053d7921ee747c46067b7d9cdd1ac86d1f1618910a7c16a2be4","checked_on":"2026-10-28"},{"id":"sweets-placemat","kind":"特典","title":"纸餐垫：每人每次入店 1 张","text_zh":"点联动菜单即可领取 A4 纸餐垫，每人每次入店 1 张，可选 A / B 款。并非每点一份菜单都能再领一张。赠品数量有限，不能根据活动仍在进行推断还有余量。","evidence_ja":"お一人様につき1枚","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_03.jpg","image_sha256":"b2ab7f73cdd13fa8dc99df53553bd7f318c34683a21fbe983abb5cefa3f58431","checked_on":"2026-10-28"},{"id":"sweets-coaster","kind":"特典","title":"杯垫：每份联动菜单 1 张，可选组别","text_zh":"每点 1 份联动菜单，随机赠送 1 张杯垫。可选 A / B 组，不能指定组内角色：A 组共 12 款（MyGO!!!!!、millsage），B 组共 18 款（Ave Mujica、梦限大MewType、一家Dumb Rock!）。不要与热饮图案的 A 组 10 款 / B 组 15 款混淆。","evidence_ja":"Aグループ（全12種）","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_03.jpg","image_sha256":"b2ab7f73cdd13fa8dc99df53553bd7f318c34683a21fbe983abb5cefa3f58431","checked_on":"2026-10-28"},{"id":"sweets-goods-limits","kind":"购买","title":"每次入店只结账一次；盲盒分系列限购","text_zh":"每人每次入店只能结账购买周边 1 次。普通非随机商品每种最多 3 件。随机亚克力立牌 A（10 款）最多 30 个，B（15 款）最多 45 个；随机大号透明卡（5 款）最多 15 张。随机徽章 A / B / C / D / E 各系列（每系列 6 款）分别最多 20 个。主办方可能调整或取消限购，以门店当天公告为准。","evidence_ja":"お一人様1回のご入店につき1会計","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2610_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E8%B3%BC%E5%85%A5%E5%88%B6%E9%99%90POP.jpg","image_sha256":"4c7498cec2c375c1dd9fa099bb1a15afce82b6c3c52b23d18d41b8def26d4691","checked_on":"2026-10-28"},{"id":"sweets-goods-prices","kind":"购买","title":"商品价格与内封贴纸，不是全店满赠","text_zh":"含税售价：等身亚克力立牌 ¥1,650；随机亚克力立牌 ¥880；随机大号透明卡 ¥990；随机徽章 ¥550；6 张装贴纸套组 ¥990；75g 清汤味意面零食 ¥1,760。每份意面零食内含 5 款中随机 1 张贴纸，这是该商品内封，不是全店消费满额赠品。售罄消息可查看官方 @SP_collabo；公告更新可能晚于现场售罄，当前库存未知。","evidence_ja":"ステッカー1枚入り（全5種）","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2610_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%82%B0%E3%83%83%E3%82%BAPOP_1009.jpg","image_sha256":"0115d23f3855a14bb854047ecb913261cb5f8c6e67f4ed559fa4062957a410b2","checked_on":"2026-10-28"},{"id":"sweets-booking","kind":"预约","title":"App 预约与九地不同日程","text_zh":"官方 App 按先到先得预约座位，受理范围为到店前 35 天至前一天 20:00（日本时间）；开放时刻未公布，不支持当天通过 App 预约。同一账号同一时间只能持有 1 个有效预约，取消或完成到店后才能预约下一次。各门店起止日期不同，请使用下方门店选择器核对。部分周边计划后续通販，日期尚未公布。","evidence_ja":"来店希望日の35日前から前日の20時まで","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","image_url":null,"image_sha256":null,"checked_on":"2026-10-28"}]','[{"id":"sweets-placemat","title":"联动菜单赠 A4 纸餐垫","rule":"每人每次入店 1 张，可选 A / B 款；不随点单件数累加。","threshold_yen":null,"threshold_quantity":null,"channel":"门店","scope":"九地联动门店；各店仅在自身活动日期内适用","venue_ids":[],"starts_on":"2026-11-02","ends_on":"2026-11-29","selection":"可选","receipt_combination":"未说明","while_supplies_last":true,"image":{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_03.jpg","alt":"联动菜单赠 A4 纸餐垫官方说明","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},"source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"id":"sweets-coaster","title":"每份联动菜单赠杯垫","rule":"每份菜单赠 1 张；可选 A 组（12 款）或 B 组（18 款），组内随机，不能指定角色。","threshold_yen":null,"threshold_quantity":1,"channel":"门店","scope":"九地联动门店；各店仅在自身活动日期内适用","venue_ids":[],"starts_on":"2026-11-02","ends_on":"2026-11-29","selection":"随机","receipt_combination":"未说明","while_supplies_last":true,"image":{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2609_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%83%A1%E3%83%8B%E3%83%A5%E3%83%BC%E8%A1%A8_1001_03.jpg","alt":"每份联动菜单赠杯垫官方说明","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},"source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},{"id":"sweets-pasta-sticker","title":"意面零食内封贴纸","rule":"每份 ¥1,760 意面零食内封随机贴纸 1 张（共 5 款），不是全店满额赠品。","threshold_yen":null,"threshold_quantity":1,"channel":"门店","scope":"九地联动门店；各店仅在自身活动日期内适用","venue_ids":[],"starts_on":"2026-11-02","ends_on":"2026-11-29","selection":"随机","receipt_combination":"未说明","while_supplies_last":true,"image":{"url":"https://www.sweets-paradise.jp/wp-content/uploads/2026/10/2610_%E3%83%90%E3%83%B3%E3%83%89%E3%83%AA_%E3%82%B0%E3%83%83%E3%82%BAPOP_1009.jpg","alt":"意面零食内封贴纸官方说明","source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"},"source_url":"https://www.sweets-paradise.jp/collaboration/ournotes","checked_on":"2026-10-28"}]') on conflict do nothing;
