insert into public.events (id,slug,title_ja,title_zh,category,summary,image,fees,conditions,status,verified_at,updated_at,benefits,gallery) values ('lovelive-gigo-card-phase6-2026','lovelive-gigo-card-phase6-2026','ラブライブ！シリーズ オフィシャルカードゲーム×GiGO詳細更新のお知らせ','LoveLive! 卡牌 × GiGO 第 6 弹（含步梦）','联动咖啡厅','当前第 6 弹为五个系列的卡包插画联动，包含上原步梦。虹咲专属第 2 弹已结束；不要把旧阶段商品或特典当成本期内容。','{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/08/28/1002/iEkZ6kymUkfqYy3E/i4YJAfh04QWhUzhk.jpeg","alt":"第 6 弹卡包插画饮品公告（含步梦）","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6557","checked_on":"2026-10-28"}','联动饮品每杯 700 日元含税；餐食价格与可点项目以会场菜单为准。','["Stand 仅提供饮品与部分物贩，无餐食、甜点，也无物贩消费赠品；秋叶原2号馆不售商品。","冈山 Stand 已于 9/30 结束，未列入本期门店。这里是部分店铺目录。","本期物贩满赠是 Liella! 图案，不是虹咲图案；到店前请确认接受的特典。","所有商品及赠品余量未知，不能用活动未结束推断有货。"]','published','2026-10-28T12:00:00+09:00','2026-10-28T12:00:00+09:00','[{"id":"niji-gigo-coaster","title":"点单特典：随机杯垫（第 6 弹 5 款）","rule":"每份餐食 / 甜点盘赠 2 张，每杯饮品 / 每份芭菲赠 1 张。Stand 仅适用其实际提供的饮品，不能在那里领取餐食双份特典。","threshold_yen":null,"threshold_quantity":null,"channel":"门店","scope":"秋叶原3号馆咖啡厅及本期各 Stand 的实际提供菜单","venue_ids":[],"starts_on":"2026-10-24","ends_on":"2026-11-08","selection":"随机","receipt_combination":"未说明","while_supplies_last":true,"image":null,"source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6557","checked_on":"2026-10-28"},{"id":"gigo-phase6-shop-bonus","title":"咖啡厅物贩每满 ¥2,000：Liella! 透明生写真","rule":"仅秋叶原3号馆咖啡厅物贩结账每满 2,000 日元含税赠 1 张；第 6 弹采用 Liella! 图案，不是虹咲图案。所有 Stand 均无此物贩满赠。","threshold_yen":2000,"threshold_quantity":null,"channel":"门店","scope":"仅咖啡厅物贩；Stand 不适用","venue_ids":["niji-gigo-aki3"],"starts_on":"2026-10-24","ends_on":"2026-11-08","selection":"固定","receipt_combination":"未说明","while_supplies_last":true,"image":null,"source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6557","checked_on":"2026-10-28"}]','[{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/08/28/1002/iEkZ6kymUkfqYy3E/i4YJAfh04QWhUzhk.jpeg","alt":"第 6 弹联动饮品图","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6557","checked_on":"2026-10-28"},{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/08/28/1002/lazeFrnKSCfrZ1ZJ/2AmFYI0BiSSBktIV.jpeg","alt":"第 6 弹联动饮品图（续）","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6557","checked_on":"2026-10-28"}]') on conflict do nothing;
