insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-9cfb2d214ec41aea','official-9cfb2d214ec41aea','Guilty Kiss Musical Performance 漆黒のWanted Ghost','Guilty Kiss 音乐剧《漆黑的 Wanted Ghost》','音乐和声优活动','2026年11月22、23日在沼津市民文化中心各演两场。这是3DCG音乐剧，声优本人不登台。现场普通指定席9,800日元，SPWN一般先到先得售票至11月12日23:59（日本时间），售完可提前结束；附周边票已截止。不能以配信票入场。','{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/04/18/1002/c56700lQDN6V4XEY/N7odUamdfI4wq7eg.jpeg","alt":"Guilty Kiss 音乐剧《漆黑的 Wanted Ghost》","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","checked_on":"2026-10-29"}','[]','[]','[{"title":"四场演出","text_zh":"11月22、23日各有昼夜两场：昼场12:30入场、13:30开演；夜场16:30入场、17:30开演。四场剧情视点和音乐Live曲目不同。","evidence_ja":"公演日時\nDay.1 2026年11月22日（日）\n昼公演 拒絶への恐怖 - Fear of Rejection - 12:30開場／13:30開演\n夜公演 境遇への反発 - Against Odds - 16:30開場／17:30開演\nDay.2 2026年11月23日（月祝）\n昼公演 結果への焦燥 - Chasing Results - 12:30開場／13:30開演\n夜公演 魂の重奏 - Ensemble of Souls - 16:30開場／17:30開演\n※公演途中より、一部異なる演出と視点から結末へ至る物語をお届けします。\n舞台内容\n完全オリジナルストーリーによる、ミュージカルパフォーマンス\n※芝居と楽曲で構成される「演劇」となります。\n※加えて出演者によるカーテンコール/MCと、公演毎に楽曲が異なる「音楽ライブ」を別途で予定しております。\n※Day.2 夜公演の音楽ライブパートのみスマートフォンでの撮影をOKとする予定です。","id":"auto-9cfb2d214ec41aea-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"演出性质","text_zh":"场馆为沼津市民文化中心；出演角色是樱内梨子、津岛善子、小原鞠莉。演出为3DCG音乐剧，没有声优现场登台。","evidence_ja":"会場\n沼津市民文化センター\n出演\n桜内梨子（リリー役）、津島善子（ヨハネ役）、小原鞠莉（マリー役）\n※本公演は3DCGミュージカルであり、キャストの登壇はありません。","id":"auto-9cfb2d214ec41aea-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"现场票价与赠品","text_zh":"普通全席指定9,800日元，附周边14,800日元（含税）；附周边为梨子B5亚克力板及Guilty Kiss三款徽章。配信票价格不同，不提供现场入场资格。","evidence_ja":"チケット料金\n＜現地＞\nグッズ付き全席指定チケット：14,800円（税込）\n全席指定チケット：9,800円（税込）\n＜SPWN配信＞ ※公演同時＋アーカイブ\nグッズ付き配信チケット：7,800円（税込）\n配信チケット：4,800円（税込）\n＜VRChat配信＞ ※公演同時＋アーカイブ\nグッズ付きVRChat配信チケット：11,800円（税込）\nVRChat配信チケット：8,800円（税込）\n＜現地＞グッズ付き全席指定チケット特典\nB5アクリルパネル【桜内梨子】＋アクリルバッジ3種【Guilty Kiss】セット","id":"auto-9cfb2d214ec41aea-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"一般售票","text_zh":"普通票SPWN受理为8月28日18:00至11月12日23:59（日本时间）；沼津市民文化中心另有售票入口，只公布起售时间。附周边票9月27日23:59已截止。售完提前结束，付款失效时可能重新释放库存，不能据此保证有票。","evidence_ja":"現地チケット：一般先着\n----------\n■受付URL：\nグッズ付き全席指定チケット\nSPWN https://spwn.jp/events/evt_MAEeuurU5wuiqfJCIifc\n販売期間 2026年8月28日（金）18:00～9月27日（日）23:59まで\n全席指定チケット\nSPWN https://spwn.jp/events/evt_MAEeuurU5wuiqfJCIifc\n販売期間 2026年8月28日（金）18:00～11月12日（木）23:59まで\n沼津市民文化センター https://p-ticket.jp/numazu-ccc\n販売期間 2026年8月28日（金）18:00～\n※先着順での販売となります。予定枚数に達し次第、受付を終了いたします。\n※決済流れ等の理由により一部在庫が復活する場合もございます。\n----------","id":"auto-9cfb2d214ec41aea-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"特典领取","text_zh":"现场票特典须持票本人在演出当天领取，未领取作废，不提前或事后邮寄；不良品仅当天办理更换。","evidence_ja":"〇現地チケット\n・来場者特典は会場にてチケットをお持ちのご本人様と引き換えとなります。\n・公演当日にお受け取りができない場合は無効となります。事前・事後の発送は行いませんので、あらかじめご了承ください。\n・不良品の交換は当日のみ対応いたします。","id":"auto-9cfb2d214ec41aea-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"入场、退款与转让","text_zh":"3岁以上收费，需SPWN会员，另收手续费。除延期或取消外不能退票或更改票种；电子票不发行纸票，携带照片证件。不能转让全部同票种门票，至少一张须本人使用；不同票种或批次不能保证连座。","evidence_ja":"●注意事項●\n※3歳以上有料（入場時に確認させていただく場合がございます。）\n※お申込み時にSPWNの会員登録（無料）が必要です。\n※会場は全席指定席です。\n※チケットの他に各種手数料が必要となります。\n※イベントページ内の「申込前に注意事項を必ずお読みください」を必ずご確認いただきお申し込みください。\n※公演延期ないし中止の場合を除き、払い戻しおよびチケットの種別変更はできません。\n※券種をまたいでチケットを複数枚お申込みいただいた場合、両方当選およびいずれかのチケットのみ当選となる場合もございますのでご了承ください。\n※応募状況によっては全て落選の可能性もございます。\n※抽選、販売期間及び券種をまたいでのチケット複数枚申込では、お席を連番でご用意することはできません。あらかじめご了承ください。\n※同じ券種を複数枚お申し込みいただいた場合、全てのチケットを他人に譲渡することはできません。一枚は必ずご本人がご使用ください。\n※チケットの転売は禁止しております。\n※ご入場の際に会場にて、身分証明書の確認をさせていただく場合がございます。顔写真付きの身分証明書をご持参ください。\n※チケットは電子チケットとなります。紙媒体での発券はいたしませんのでご注意ください。\n※その他注意事項につきましては、 SPWNのイベントページ をご確認ください。","id":"auto-9cfb2d214ec41aea-rule-5","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"手机拍摄范围","text_zh":"官网仅计划允许Day2夜场的音乐Live部分用手机拍摄，不能扩大到整场演剧。","evidence_ja":"※Day.2 夜公演の音楽ライブパートのみスマートフォンでの撮影をOKとする予定です。","id":"auto-9cfb2d214ec41aea-rule-6","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=Wanted_Ghost","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","普通现场票SPWN先着销售；不需把附周边票/配信票当作CD抽选资格。售完提前结束，每天昼夜场次详见规则。"]','published','2026-10-29T12:15:33.162Z','2026-10-29T12:15:33.162Z') on conflict do nothing;
