insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-4dd06bfcf0d0abb2','official-4dd06bfcf0d0abb2','ラブライブ！蓮ノ空女学院スクールアイドルクラブ Link Live Dream ～おいでよ！石川大観光Ⅱ～｜LIVE＆EVENT','莲之空 Link Live Dream「来吧！石川大观光Ⅱ」','音乐和声优活动','2026年11月28、29日在金泽石川县产业展示馆4号馆举办。一般销售第一次抽选已于10月25日截止；第二次为10月31日12:00至11月8日23:59（日本时间），信用卡付款限定，每人每场最多2张。','{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/05/1002/EAZx7GnmotnpmGJZ/y2mnAXODKayAqlBL.jpeg","alt":"莲之空 Link Live Dream「来吧！石川大观光Ⅱ」","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream","checked_on":"2026-10-29"}','[]','[]','[{"title":"场次","text_zh":"11月28日15:30入场、16:30开演；29日14:30入场、15:30开演，均为日本时间。","evidence_ja":"【日程】\nDay.1 2026年11月28日(土) 15:30開場／16:30開演\nDay.2 2026年11月29日(日) 14:30開場／15:30開演\n【会場】\n石川・石川県産業展示館（4号館）","id":"auto-4dd06bfcf0d0abb2-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"两轮一般抽选","text_zh":"第一次10月10日至25日已截止；第二次10月31日12:00至11月8日23:59，11月13日13:00起公布结果，每人每场最多2张，仅信用卡支付。","evidence_ja":"＜一般発売（1次抽選）＞\n----------\n■受付URL： https://eplus.jp/hasunosora-lld/\n■受付期間：2026年10月10日（土）12:00～10月25日（日）23:59\n■当落発表：2026年10月31日（土）13:00～\n■入金期間：2026年10月31日（土）13:00～11月3日（火・祝）21:00\n※枚数制限：お一人様、 1公演につき2枚までお申込み可能。（複数公演申込可能）\n----------\n＜一般発売（2次抽選）＞\n----------\n■受付URL： https://eplus.jp/hasunosora-lld/\n■受付期間：2026年10月31日（土）12:00～11月8日（日）23:59\n■当落発表：2026年11月13日（金）13:00～\n※枚数制限：お一人様、 1公演につき2枚までお申込み可能。（複数公演申込可能）\n※クレジットカード決済のみ受付となります。\n----------","id":"auto-4dd06bfcf0d0abb2-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"门票","text_zh":"指定席13,000日元，U-20为6,500日元，升席另加13,000日元；U-20申请者与同行者都须当天未满20岁。","evidence_ja":"【チケット料金】\n全席指定：13,000円（税込）\nU-20割引チケット：6,500円（税込）\nアップグレードチケット（グッズ付き）：＋13,000円\n----------\n＜U-20割引チケットについて＞\n本公演は、20歳未満の方にもご参加いただきやすくするため、対象の方に向け「U-20割引チケット」を販売いたします。\n・ 公演当日時点で20歳未満の方が購入できるチケットとなります。\n・一般発売に合わせ販売予定です。枚数には限りがございますので、あらかじめご了承ください。\n・当日はご入場にあたり、年齢を確認できる身分証明書を確認させていただきます。\n・U-20割引チケットはお一人様1公演につき2枚までお申込みいただけますが、同行者の方も公演当日時点で20歳未満の方に限ります。あらかじめご了承ください。\n----------","id":"auto-4dd06bfcf0d0abb2-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"升席","text_zh":"升席抽选10月17日至25日已截止，仅原最速先行中选并付款者可申请；同行者、账号及张数须与原中选记录一致。","evidence_ja":"＜アップグレード抽選受付＞\n----------\n■受付期間：2026年10月17日（土）12:00～10月25日（日）23:59\n■当落発表：2026年10月31日（土）13:00～\n※クレジットカード決済のみ受付となります。\n----------\n※受付URLは最速先行抽選でチケット購入済みの方でお申込ご本人様のみへイープラスよりメールでご案内いたします。\nメールが届かない場合はお申込ご本人様のイープラスサイト内「申込み履歴（申込み状況照会）」の当選したチケットの詳細から受付URLをご確認いただけます。\n▼申込み履歴（申込み状況照会）\nhttps://eplus.jp/jyoukyou/\n※同行者様には受付URLのご案内はいたしません。\n＜お申込み条件＞\n【対象のお客様】\n最速先行抽選受付にて「全席指定：13,000円（税込）」のチケットにご当選され、ご入金が完了のお申込ご本人様。\n※ご当選・ご入金された公演日・会員情報と同一アカウントのお申込ご本人様が抽選対象となります。最速先行抽選受付にて当選された申込者様のアカウントでお申込みください。登録情報を変更されたり、異なるアカウント情報、異なる同行者でお申込みをされた場合、無効となりますのでご注意ください。\n※同一アカウントのお申込みでも、最速先行抽選受付で当選された同行者様が、「アップグレードチケット」の受付で申込者様としてお申込みをされた場合は、無効となりますのでご注意ください。\n例）最速先行抽選受付にてAさんが申込者、Bさんが同行者として当選\n⇒「アップグレードチケット」の受付はBさんが申込者、Aさんが同行者の場合無効\n※最速先行抽選受付にて2枚購入済みの場合、2枚全てが「アップグレードチケット」の対象となり、一部のみを「アップグレードチケット」としてお申込みは無効となります。\n必ず、最速先行抽選受付にて当選したチケットと同枚数にて、「アップグレードチケット」をお申込みください。\n※チケット代金の他に各種手数料が必要となります。\n※アップグレードチケットご購入者様は優先配席を保証いたしますが、エリアの一部の席につきまして、「全席指定」の方が配席される可能性がございます。何卒ご理解の程、お願い申し上げます。\n※「アップグレードチケット」に抽選で落選した場合は、当選済みの「全席指定」でのご入場・ご観覧となります。","id":"auto-4dd06bfcf0d0abb2-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"实名与费用","text_zh":"3岁以上收费；需eplus会员，票价外另有手续费。申请者及同行者登记人脸照片，携带照片身份证件。","evidence_ja":"●注意事項●\n※3歳以上有料\n※お申込み時にイープラスの会員登録（無料）が必要です。\n※必ず受付画面にて、注意事項をご確認の上、お申込みください。\n※抽選販売分は先着順での受付ではございませんので、受付期間内にお申込みください。当落および座席などは、先着順ではなく、期間内にお申込みいただいた中から抽選で決定いたします。\n※お席に関してのお問合せには、お答えできません。\n※お申込み内容の変更・取消しは受付期間中のみおこなえます。当選後の変更・取消し(購入辞退)は一切お受けできませんのでご注意ください。\n※チケット代金の他に各種手数料が必要となります。\n※アルコール類の持込、及び飲酒してのご入場は固くお断りいたします。\n※開場・開演時間、出演者は諸事情により変更になる場合がございます。それに伴うチケット代・交通費等の払い戻しはいたしません。あらかじめご了承ください。\n※ご来場のお客様におかれましては、公演における注意事項を必ずお読みいただき、遵守くださいますようお願いいたします。ご協力いただけない場合、ご入場いただけない可能性もございますので、あらかじめご了承ください。\n※顔認証入場システムを利用したチケット販売のため、顔写真登録が必要となります。必ず来場者ご本人様がお申込みください。（チケットを複数枚購入される場合、同行者の顔写真登録も必要となります。）\n※顔認証入場システムでご本人と判断できない場合、顔写真付きの公的身分証でご本人確認をさせていただきますので、必ずご持参ください。","id":"auto-4dd06bfcf0d0abb2-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","一般第二次抽选，只能信用卡付款，每人每场2张。商品附券先行已截止，不能再购买商品来参加已结束的轮次。"]','published','2026-10-29T12:15:33.162Z','2026-10-29T12:15:33.162Z') on conflict do nothing;
