insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-81f284dd403980ef','official-81f284dd403980ef','ラブライブ！スーパースター!! Liella! 8th LoveLive! Tour ～Our Song, Our Dreams～','Liella! 八巡「Our Song, Our Dreams」','音乐和声优活动','2027年3月6–7日东京有明Arena、4月24–25日福冈Marine Messe B馆、5月8–9日名古屋Port Messe第1展示馆。每站Day1和Day2对应不同商品附券和报名开始日，均于12月14日23:59（日本时间）截止；票价和开演时间尚待公布。','{"url":"https://www.lovelive-anime.jp/yuigaoka/common/api/image.php?img_path=/lovelive/jp/live/2026/09/03/1002/NxLuZEh2hhMek7is/p1h3XcoSoKvN2x1g.jpeg","alt":"Liella! 八巡「Our Song, Our Dreams」","source_url":"https://www.lovelive-anime.jp/yuigaoka/live/live_detail.php?p=8thlivetour","checked_on":"2026-10-29"}','[]','[]','[{"title":"三站日程","text_zh":"东京3月6–7日、福冈4月24–25日、名古屋5月8–9日；不可将爱知县作为城市名称。","evidence_ja":"＜東京公演＞\n【日程】\nDay.1 2027年3月6日（土）\nDay.2 2027年3月7日（日）\n【会場】\n東京・有明アリーナ\n【公演に関するお問い合わせ先】\nインフォメーションデスク https://information-desk.info/\n＜福岡公演＞\n【日程】\nDay.1 2027年4月24日（土）\nDay.2 2027年4月25日（日）\n【会場】\n福岡・マリンメッセ福岡B館\n【公演に関するお問い合わせ先】\nBEA 092−712−4221（平日12:00〜16:00）\n＜愛知公演＞\n【日程】\nDay.1 2027年5月8日（土）\nDay.2 2027年5月9日（日）\n【会場】\n愛知・ポートメッセなごや 第1展示館\n【公演に関するお問い合わせ先】\nキョードー東海 052-972-7466 （月～金 12:00～18:00/土 10:00～13:00（※日曜・祝日は休業））","id":"auto-81f284dd403980ef-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/live/live_detail.php?p=8thlivetour","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"Day1附券","text_zh":"各站Day1使用11月18日发行的八巡主题歌迷你专辑附券；11月18日12:00至12月14日23:59受理，每序列号各站Day1分别最多4张。12月19日13:00预计公布结果，付款至22日21:00，日本时间。","evidence_ja":"★お申込み対象公演：東京Day.1公演、福岡Day.1公演、愛知Day.1公演\n2026年11月18日（水）発売『ラブライブ！スーパースター!! Liella! 8th LoveLive! Tour ～Our Song, Our Dreams～』テーマソングミニアルバム封入の申込券にて受付\n----------\n■受付期間：2026年11月18日（水）12:00～12月14日（月）23:59\n■当落発表：2026年12月19日（土）13:00予定\n■入金期間：2026年12月19日（土）13:00～12月22日（火）21:00\n※枚数制限：『シリアルNo.』1つにつき、各会場のDay.1公演にそれぞれ4枚までお申込み可能（複数公演申込可能）。\n----------","id":"auto-81f284dd403980ef-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/live/live_detail.php?p=8thlivetour","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"Day2附券","text_zh":"各站Day2使用11月27日发行的Fan Disc第2弹附券；11月27日12:00至12月14日23:59受理，每序列号各站Day2分别最多4张，结果及付款时间与Day1相同。","evidence_ja":"★お申込み対象公演：東京Day.2公演、福岡Day.2公演、愛知Day.2公演\n2026年11月27日（金）発売「ラブライブ！スーパースター!! ファンディスク第2弾 わくわく地域活動 ～Liella!と結ぶプロジェクト特別編～」封入の申込券にて受付\n----------\n■受付期間：2026年11月27日（金）12:00～12月14日（月）23:59\n■当落発表：2026年12月19日（土）13:00予定\n■入金期間：2026年12月19日（土）13:00～12月22日（火）21:00\n※枚数制限：『シリアルNo.』1つにつき、各会場のDay.2公演にそれぞれ4枚までお申込み可能（複数公演申込可能）。\n----------","id":"auto-81f284dd403980ef-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/live/live_detail.php?p=8thlivetour","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"尚未公布","text_zh":"开场、开演时间及票价后续公布，升席安排也待后续公告。","evidence_ja":"※開場・開演時間、チケット代など、そのほかの詳細は後日ご案内いたします。","id":"auto-81f284dd403980ef-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/live/live_detail.php?p=8thlivetour","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"实名及年龄","text_zh":"3岁以上收费；申请者与同行者均需登记人脸照片并携带带照片的官方身份证件，需eplus会员；抽选不是先到先得。","evidence_ja":"注意事項\n※3歳以上有料\n※お申込み時にイープラスの会員登録（無料）が必要です。\n※必ず受付画面にて、注意事項をご確認の上、お申込みください。\n※抽選販売分は先着順での受付ではございませんので、受付期間内にお申込みください。当落および座席などは、先着順ではなく、期間内にお申込みいただいた中から抽選で決定いたします。\n※お席に関してのお問合せには、お答えできません。\n※お申込み内容の変更・取消しは受付期間中のみおこなえます。当選後の変更・取消し(購入辞退)は一切お受けできませんのでご注意ください。\n※チケット代金の他に各種手数料が必要となります。\n※アルコール類の持込、及び飲酒してのご入場は固くお断りいたします。\n※開場・開演時間、出演者は諸事情により変更になる場合がございます。それに伴うチケット代・交通費等の払い戻しはいたしません。あらかじめご了承ください。\n※ご来場のお客様におかれましては、公演における注意事項を必ずお読みいただき、遵守くださいますようお願いいたします。ご協力いただけない場合、ご入場いただけない可能性もございますので、あらかじめご了承ください。\n※顔認証入場システムを利用したチケット販売のため、顔写真登録が必要となります。必ず来場者ご本人様がお申込みください。（チケットを複数枚購入される場合、同行者の顔写真登録も必要となります。）\n※顔認証入場システムでご本人と判断できない場合、顔写真付きの公的身分証でご本人確認をさせていただきますので、必ずご持参ください。\n▼顔認証入場システムのご利用について\nhttps://eplus.jp/faceticket_about/\n■同行者登録とは？\nhttps://eplus.jp/sf/guide/fellow-ep/\n■【同行者登録】手続きはこちら\nhttps://member.eplus.jp/update-dokosha\n※受付開始前からお手続きいただけます。","id":"auto-81f284dd403980ef-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/live/live_detail.php?p=8thlivetour","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","各站Day1、Day2使用不同商品附券，请分别查看场次。"]','published','2026-10-29T12:48:06.373Z','2026-10-29T12:48:06.373Z') on conflict do nothing;
