insert into public.releases (id,slug,status,document,updated_at) values ('bushiroad-20th-anniversary-book','bushiroad-20th-anniversary-book','published','{"id":"bushiroad-20th-anniversary-book","slug":"bushiroad-20th-anniversary-book","title":"ブシロード20周年記念 アニバーサリーブック","franchise_ids":["bang-dream","ave-mujica","starlight","lovelive"],"release_on":"2027-01-08","summary":"武士道20周年纪念书：附最速先行抽选申込券。Live 将于 2027 年 6 月 12、13 日在横滨 Arena 举办。","status":"published","updated_at":"2026-10-28T00:00:00+09:00","editions":[{"id":"book","label":"纪念书","sku":"","price_yen":1760,"eligibility":"官方公布的书内附录包含 Live 最速先行抽选申込券。使用方法后续公开；不能据此假定一书可申请两天或具体张数。"}],"lotteries":[{"id":"bushiroad-20th-fastest","title":"ブシロード20周年記念ライブ 最速先行","edition_ids":["book"],"event_slug":"bushiroad-20th-live-2027","live_dates":["2027-06-12","2027-06-13"],"venue":"横浜アリーナ（横滨 Arena）","window":{"opens_on":null,"opens_at":null,"closes_at":null,"note":"官方明确说明申请详情后日公开。抽选开始、截止、当落与付款时间均尚未公布。"},"conditions":["需要纪念书附带的最速先行抽选申込券。","申请入口、单券申请次数、可报天数、每次张数及费用尚未公布。","出演者具体演出日程尚未公布；已公布的阵容不代表每天全部出演。","另一份附录是「カードゲーム祭2027」PR卡兑换券；书中不直接封入PR卡，也不是另一张Live门票。"],"source_url":"https://live.bushiroad-music.com/bushiroad_20thlive/"}],"offers":[{"id":"book-shop-0","retailer":"Amazon","edition_ids":["book"],"bonus":"独立店铺特典尚未核实。书内两种附录属于商品内容，不能视为该店独家赠品。","preorder":{"opens_on":null,"opens_at":null,"closes_at":null,"note":"出版社列为销售渠道；本条未确认该店预约起止或当前库存。"},"source_url":"https://bushiroad-works.com/bushiroad20thbook/","shop_url":"https://www.amazon.co.jp/dp/B0HMC111ZF","note":"销售链接来自出版社公告，不代表已核实该店可下单。","retailer_id":null},{"id":"book-shop-1","retailer":"ブシロード オンラインストア","edition_ids":["book"],"bonus":"独立店铺特典尚未核实。书内两种附录属于商品内容，不能视为该店独家赠品。","preorder":{"opens_on":null,"opens_at":null,"closes_at":null,"note":"2026-10-28 核实页面标为预约商品，未列出固定预约开始或截止；并非实时库存查询。"},"source_url":"https://bushiroad-store.com/products/2000328359765","shop_url":"https://bushiroad-store.com/products/2000328359765","note":"网店每人限购10件，不等于每人可以申请10张门票。页面说明2027年1月8日以后送达，不承诺当日到货；不提供海外配送。","retailer_i